let fila = [];

function chegarPaciente(nome) {
    fila.push(nome);

    console.log(`${nome} chegou à clínica.`);
    exibirFila();
}

function chamarProximo() {
    if (fila.length > 0) {
        let paciente = fila.shift();

        console.log(`Chamando paciente: ${paciente}`);
    } else {
        console.log("Não há pacientes na fila.");
    }

    exibirFila();
}

function exibirFila() {
    console.log("Fila atual:");

    if (fila.length === 0) {
        console.log("Fila vazia.");
    } else {
        fila.forEach(paciente => {
            console.log(paciente);
        });
    }

    console.log("-------------------");
}

// Simulação

chegarPaciente("João");
chegarPaciente("Maria");
chegarPaciente("Pedro");
chegarPaciente("Ana");
chegarPaciente("Carlos");

chamarProximo();
chamarProximo();
chamarProximo();